export function getArticle(slug: string): Article | undefined {
  return ARTICLES.find(a => a.slug === slug)
}

/**
 * Returns true once an article's publishedAt date has arrived
 * (compared in UTC, publishedAt format 'YYYY-MM-DD').
 *
 * This is the single source of truth for the published/scheduled
 * distinction, reused by getPublishedArticles() and by the article
 * page to decide on noindex + the "scheduled" preview badge.
 */
export function isArticlePublished(article: Article): boolean {
  const now = new Date()
  return new Date(article.publishedAt) <= now
}

/**
 * Returns only articles whose publishedAt date has already arrived,
 * sorted with the most recently published article first.
 *
 * This is the single source of truth for what's publicly visible:
 * future-dated articles can live in ARTICLES ahead of time and will
 * simply stay invisible until a build runs on/after their publishedAt.
 */
export function getPublishedArticles(): Article[] {
  return ARTICLES.filter(isArticlePublished).sort(
    (a, b) => new Date(b.publishedAt).getTime() - new Date(a.publishedAt).getTime()
  )
}

export function getAllArticleSlugs(): string[] {
  return getPublishedArticles().map(a => a.slug)
}

/**
 * Returns slugs for ALL articles in ARTICLES, published or not.
 *
 * Used only by generateStaticParams() on the article page so that
 * future-dated articles can be previewed by direct URL (with output:
 * 'export', Next.js 404s any slug missing from generateStaticParams,
 * even in dev). Never use this for sitemap.xml or the /journal listing
 * — those must stay on getAllArticleSlugs() / getPublishedArticles().
 */
export function getAllArticleSlugsIncludingFuture(): string[] {
  return ARTICLES.map(a => a.slug)
}
